with metrics as (select id, dept_name, location, budget, row_number() over (order by budget desc, id) as row_seq, lag(budget, 1) over (order by budget, id) as prev_budget, rank() over w_recent as budget_rank, sum(budget) over (partition by dept_name order by budget, id rows between unbounded preceding and current row) as running_budget, avg(budget) over (partition by location, dept_name order by budget, id rows between 3 preceding and 1 preceding) as budget_avg_3_prior from departments window w_recent as (partition by location order by budget desc nulls last)) select case when budget >= 3740000 then 'LARGE' else 'SMALL' end as budget_tier, count(distinct location) as distinct_locations, size(collect_set(location)) as num_locations, percentile_approx(row_seq, array(0.25, 0.5, 0.75)) as row_seq_quartiles from metrics group by case when budget >= 3740000 then 'LARGE' else 'SMALL' end;
